// ============================================================
// FSMGuard Patch - Deadlock Trap
// CWE: CWE-1280
// Parameter: lockdown
// Strictness: strict
// ============================================================
// This patch adds deadlock detection for state STUCK
// Added by FSMGuard Stage 08 based on RL agent decision



// Lockdown mode: Halt all operations on deadlock
always @(posedge clk) begin
    if (current_state == STUCK) begin
        // Critical deadlock - initiate lockdown
        lockdown = 1'b1;
        next_state = RESET;
    end
end



// ============================================================
// End FSMGuard Patch
// ============================================================
